/**
 * Rate Limiter Middleware — Protects against brute-force and DDoS.
 * Generated by BackendForge
 */

const rateLimit = require('express-rate-limit');
const { env } = require('../config/env');

// General API rate limiter
const rateLimiter = rateLimit({
  windowMs: parseInt(env.RATE_LIMIT_WINDOW_MS) || 15 * 60 * 1000, // 15 minutes
  max: parseInt(env.RATE_LIMIT_MAX_REQUESTS) || 100,
  message: {
    success: false,
    message: 'Too many requests. Please try again later.',
    code: 'RATE_LIMIT_EXCEEDED',
  },
  standardHeaders: true,
  legacyHeaders: false,
  keyGenerator: (req) => req.ip,
});

// Stricter limiter for auth endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10, // 10 login attempts per 15 min
  message: {
    success: false,
    message: 'Too many login attempts. Please try again after 15 minutes.',
    code: 'AUTH_RATE_LIMIT',
  },
  standardHeaders: true,
  legacyHeaders: false,
});

// Admin endpoint limiter
const adminLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: parseInt(env.ADMIN_RATE_LIMIT_MAX) || 20,
  message: {
    success: false,
    message: 'Admin rate limit exceeded.',
    code: 'ADMIN_RATE_LIMIT',
  },
  standardHeaders: true,
  legacyHeaders: false,
});

// Payment endpoint limiter
const paymentLimiter = rateLimit({
  windowMs: 60 * 1000, // 1 minute
  max: 5,
  message: {
    success: false,
    message: 'Too many payment attempts. Please wait a moment.',
    code: 'PAYMENT_RATE_LIMIT',
  },
});

module.exports = { rateLimiter, authLimiter, adminLimiter, paymentLimiter };
